"""Configure an OHOS project generated by the pinned Flutter OHOS SDK."""
import json
from pathlib import Path
import re
import shutil
import sys

root = Path(__file__).resolve().parents[1]
ohos = root / 'ohos'
entry = ohos / 'entry' / 'src' / 'main' / 'ets'
if not (entry / 'entryability' / 'EntryAbility.ets').exists():
    raise SystemExit('Generate the OHOS platform with the pinned Flutter SDK first.')
plugins = entry / 'plugins'
plugins.mkdir(exist_ok=True)
shutil.copyfile(root / 'platform/ohos/QiyouDevicePlugin.ets', plugins / 'QiyouDevicePlugin.ets')
(entry / 'entryability' / 'EntryAbility.ets').write_text('''import { FlutterAbility, FlutterEngine } from '@ohos/flutter_ohos';
import { GeneratedPluginRegistrant } from '../plugins/GeneratedPluginRegistrant';
import QiyouDevicePlugin from '../plugins/QiyouDevicePlugin';
export default class EntryAbility extends FlutterAbility {
  configureFlutterEngine(engine: FlutterEngine): void {
    super.configureFlutterEngine(engine);
    GeneratedPluginRegistrant.registerWith(engine);
    engine.getPlugins().add(new QiyouDevicePlugin());
  }
}
''', encoding='utf-8')
profile_file = ohos / 'build-profile.json5'
profile = json.loads(re.sub(r',\s*([}\]])', r'\1', profile_file.read_text(encoding='utf-8')))
profile['app']['signingConfigs'] = []
for product in profile['app']['products']:
    product.pop('signingConfig', None)
    product['compatibleSdkVersion'] = 17
    if len(sys.argv) > 1:
        product['targetSdkVersion'] = int(sys.argv[1])
profile_file.write_text(json.dumps(profile, indent=2) + '\n', encoding='utf-8')
for path in ohos.rglob('string.json'):
    if 'ohosTest' in str(path):
        continue
    data = json.loads(path.read_text(encoding='utf-8'))
    for item in data.get('string', []):
        if item.get('name') in {'app_name', 'EntryAbility_label'}:
            item['value'] = '栖游'
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
icon = root / 'assets' / 'brand' / 'icon.png'
if icon.exists():
    for target in [ohos / 'AppScope/resources/base/media/app_icon.png',
                   ohos / 'entry/src/main/resources/base/media/icon.png']:
        shutil.copyfile(icon, target)
print('OHOS entry, secure storage bridge and unsigned build profile prepared.')
